// where the reference keeps its recovery crane (ours parks there)
const CRANE_SPOTS = [[299.4, 374.1]];

const widthAt = (p) => {
  const W = WIDTHS, L = W[W.length - 1][0] + 20, s = ((p.s % L) + L) % L;
  let i = 0; while (i < W.length - 1 && W[i + 1][0] <= s) i++;
  const a = W[i], b = W[(i + 1) % W.length], span = (b[0] > a[0] ? b[0] : L) - a[0];
  return a[1] + (b[1] - a[1]) * Math.min(1, (s - a[0]) / (span || 1));
};
export function buildSuzuka(scene, opts = {}) {
  return buildCircuit(scene, {
    name: 'suzuka', title: 'TEST TRACK', outline: OUTLINE, elevation: ELEVATION, widthAt, barriers: BARRIERS, craneSpots: CRANE_SPOTS, width: 12, straightWidth: 14, official: [],
    pit: { x0: 13, x1: 24, z0: -215, z1: 175 }, garages: [-186, 150], stand: [-34, -150, 150], standFence: [-14, -200, 200],
  }, opts);
}
